import re
import time
import logging
from taf.internal.managedobject import ManagedObject
from taf.internal.portforwarding.exceptions import NotFoundBindIp


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class KubectlPortForward(ManagedObject):

    _COMMAND_FORMAT = "kubectl port-forward -n {namespace} {pod} :{service_port} --address 0.0.0.0"

    def __init__(self,
                 namespace,
                 pod,
                 port,
                 **kwargs):
        super(KubectlPortForward, self).__init__(**kwargs)
        self._namespace = namespace
        self._pod = pod
        self._bind_port = None
        self._port = port

        self._executor = None

        self._stdin = None
        self._stdout = None
        self._stderr = None
        self._waitingseconds = 3

    def attach_executor(self, executor):
        self._executor = executor
        self.add_prerequisite(self._executor)

    @property
    def bind_port(self):
        return self._bind_port

    def _setup(self):
        command = self._get_formatted_command()

        self._stdin, self._stdout, self._stderr = self._executor.start(
            command=command,
            use_tty=True)
        time.sleep(self._waitingseconds)
        self._bind_port = self._parse_bind_port()

        self._executor.ssh_connection.wait_until_listen(
            host="0.0.0.0",
            port=self._bind_port)

    def _get_formatted_command(self):
        return self._COMMAND_FORMAT.format(namespace=self._namespace,
                                           pod=self._pod,
                                           service_port=self._port)

    def _parse_bind_port(self):
        """
        parse "Forwarding from 0.0.0.0:34067 -> 15057"
        """
        output = self._stdout.readline()
        logger.debug("get kubectl output {}".format(output))
        regex = u"0\.0\.0\.0:(\d+)"
        res = re.search(regex, output)
        if not res:
            raise NotFoundBindIp(output)

        bind_port = res.group(1)
        logger.debug("parsed bind port is {}".format(bind_port))
        return int(bind_port)

    def _teardown(self):
        if not self._stdin.channel.exit_status_ready():
            self._stdin.write("\x03")
            self._stdin.flush()
        exit_status = self._stdin.channel.recv_exit_status()
        logger.debug("exit_status=%r" % exit_status)
